def solve(g):
    H,W=len(g),len(g[0])
    regs=[]; seen=[[False]*W for _ in range(H)]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=0 and not seen[i][j]:
                col=g[i][j]; dq=[(i,j)]; cells=[]
                while dq:
                    r,c=dq.pop(); cells.append((r,c))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        nr,nc=r+dr,c+dc
                        if 0<=nr<H and 0<=nc<W and g[nr][nc]==col and not seen[nr][nc]:
                            seen[nr][nc]=True; dq.append((nr,nc))
                a=min(r for r,_ in cells); b=min(c for _,c in cells)
                e=max(r for r,_ in cells); f=max(c for _,c in cells)
                regs.append({'col':col,'a':a,'b':b,'e':e,'f':f,'cells':cells})
    regs.sort(key=lambda t:len(t['cells']), reverse=True)
    n=len(regs)
    outg=[row[:] for row in g]
    for k,t in enumerate(regs):
        newcol=regs[n-1-k]['col']
        for r,c in t['cells']:
            outg[r][c]=newcol
    return outg
